/**
 * Layanan penyimpanan PDF lokal sementara untuk transfer data antar taskpane dan jendela dialog.
 * Menggunakan IndexedDB untuk kapasitas besar (>50MB) dengan fallback localStorage.
 * 100% lokal di memori/browser lokal pengguna (Zero Exfiltration).
 */

const DB_NAME = "ExcelPrintStudioDB";
const STORE_NAME = "pdf_preview_store";
const KEY = "active_pdf";

function openDB(): Promise<IDBDatabase> {
  return new Promise((resolve, reject) => {
    if (typeof indexedDB === "undefined") {
      reject(new Error("IndexedDB tidak didukung di lingkungan ini."));
      return;
    }

    const request = indexedDB.open(DB_NAME, 1);

    request.onupgradeneeded = () => {
      const db = request.result;
      if (!db.objectStoreNames.contains(STORE_NAME)) {
        db.createObjectStore(STORE_NAME);
      }
    };

    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
}

/**
 * Konversi Uint8Array ke string Base64 yang aman untuk buffer besar (chunking 8KB).
 */
export function uint8ArrayToBase64(bytes: Uint8Array): string {
  let binary = "";
  const len = bytes.byteLength;
  const chunkSize = 8192;
  for (let i = 0; i < len; i += chunkSize) {
    const chunk = bytes.subarray(i, Math.min(i + chunkSize, len));
    binary += String.fromCharCode.apply(null, Array.from(chunk));
  }
  return window.btoa(binary);
}

/**
 * Konversi string Base64 kembali ke Uint8Array.
 */
export function base64ToUint8Array(base64: string): Uint8Array {
  const binary = window.atob(base64);
  const len = binary.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binary.charCodeAt(i);
  }
  return bytes;
}

/**
 * Simpan data PDF ke IndexedDB dan localStorage untuk pratinjau dialog.
 */
export async function storePdfForPreview(data: Uint8Array): Promise<void> {
  // 1. Simpan ke IndexedDB (dapat menampung puluhan MB tanpa batas kuota sempit)
  try {
    const db = await openDB();
    await new Promise<void>((resolve, reject) => {
      const tx = db.transaction(STORE_NAME, "readwrite");
      const store = tx.objectStore(STORE_NAME);
      const req = store.put(data, KEY);
      req.onsuccess = () => resolve();
      req.onerror = () => reject(req.error);
    });
  } catch (err) {
    console.warn("[pdfStorage] IndexedDB put gagal, mencoba fallback:", err);
  }

  // 2. Simpan juga ke localStorage jika ukurannya di bawah 4MB untuk sinkronisasi instan
  if (data.byteLength < 4 * 1024 * 1024) {
    try {
      const base64 = uint8ArrayToBase64(data);
      localStorage.setItem("eps_preview_pdf_base64", base64);
      localStorage.setItem("eps_preview_pdf_size", String(data.byteLength));
      localStorage.setItem("eps_preview_pdf_time", String(Date.now()));
    } catch (err) {
      console.warn("[pdfStorage] localStorage quota exceeded, IndexedDB akan digunakan:", err);
    }
  }
}

/**
 * Ambil data PDF dari IndexedDB atau localStorage untuk ditampilkan di dialog.
 */
export async function getStoredPdfForPreview(): Promise<Uint8Array | null> {
  // 1. Coba baca dari IndexedDB
  try {
    const db = await openDB();
    const result = await new Promise<Uint8Array | null>((resolve, reject) => {
      const tx = db.transaction(STORE_NAME, "readonly");
      const store = tx.objectStore(STORE_NAME);
      const req = store.get(KEY);
      req.onsuccess = () => {
        if (req.result) {
          // req.result bisa berupa Uint8Array atau ArrayBuffer
          const val = req.result instanceof Uint8Array ? req.result : new Uint8Array(req.result);
          resolve(val);
        } else {
          resolve(null);
        }
      };
      req.onerror = () => reject(req.error);
    });

    if (result && result.byteLength > 0) {
      return result;
    }
  } catch (err) {
    console.warn("[pdfStorage] Gagal membaca dari IndexedDB:", err);
  }

  // 2. Fallback baca dari localStorage
  try {
    const base64 = localStorage.getItem("eps_preview_pdf_base64");
    if (base64) {
      return base64ToUint8Array(base64);
    }
  } catch (err) {
    console.warn("[pdfStorage] Gagal membaca dari localStorage:", err);
  }

  return null;
}
